input.command:
node --input-type=module -e "
import { convert } from './ocr-numbers.js';
// height not multiple of 4
try { convert(' _ 
| |
|_|'); console.log('FAIL: no height error'); }
catch (e) { console.log('OK height error:', e.message); }
// width not multiple of 3
try { convert(' _ 
| |
|_|
  '); console.log('FAIL: no width error'); }
catch (e) { console.log('OK width error:', e.message); }
// valid multi-line
console.log('multi:', convert(' _ 
| |
|_|

 _ 
|_ 
 _|
   '));
"

node --input-type=module -e "
import { convert } from './ocr-numbers.js';
// one line is 4 chars wide -> max width 4, not a multiple of 3
try { convert(' _  \n| |\n|_|\n    '); console.log('FAIL: no width error'); }
catch (e) { console.log('OK width error:', e.message); }
" 2>/dev/null
